    scwin.pasteDataFormatter = function(copiedData) {
        debugger;
        if (!copiedData) {
            return false;
        }
        if (this.focusedCell.length > 1) {
            this.options.pasteOption = "focus";
        } else {
            this.options.pasteOption = "";
            return copiedData;
        }
        // 데이터를 그리드뷰 전체를 채울만큼 크게 만들어버린다.
        window.rowCnt = this.getDataLength();
        window.colCnt = this.getTotalCol();
        if (copiedData.split('\n').length == 1 &&
            copiedData.split('\n')[0].split('\t').length == 1) {
            window.firstData = copiedData.split('\n')[0].split('\t')[0];
            window.result = Array(rowCnt).join('.').split('.');
            for (window.i = 0; i < rowCnt; i++) {
                for (window.j = 0; j < colCnt; j++) {
                    result[i] += (j !== colCnt - 1) ?
                        firstData + "\t" :
                        firstData;
                }
            }
            return result.join("\n");
        } else {
            return copiedData;
        }
    };
}
